export const PARK_SOURCES={nrcan:'https://open.canada.ca/data/en/dataset/9e1507cd-f25c-4c64-995b-6563bf9d65bd',cpcad:'https://open.canada.ca/data/en/dataset/6c343726-1e92-451a-876a-76e17d398a1c',plan:'https://parks.canada.ca/pn-np/on/rouge/info/gestion-management/gestion-management-2019',law:'https://laws-lois.justice.gc.ca/eng/acts/R-8.55/FullText.html'};
export function validParkData(data,ids){
 return data?.coverageStatus==='unresolved'&&data.features?.length===2&&['nrcan','cpcad'].every(id=>data.features.some(f=>f.properties?.id===id))&&data.mapBounds?.length===2&&data.mapBounds.every(p=>p.length===2&&p.every(Number.isFinite))&&ids.every(id=>data.corridors?.[id]?.coverageStatus==='unresolved'&&data.corridors[id].parkWideConclusion===null&&['nrcan','cpcad'].every(key=>{const d=data.corridors[id].records?.[key];return typeof d?.intersects==='boolean'&&Number.isFinite(d.overlapMetres)&&d.overlapMetres>=0&&(d.intersects||d.overlapMetres===0);}));
}
export function parkOverlap(d){return d.intersects?(d.overlapMetres<10?'Boundary contact / under 10 m':'~'+(Math.round(d.overlapMetres/10)*10).toLocaleString()+' m of mapped overlap'):'No overlap in this record';}
export function parksDetail(c){
 const d=c.parks;
 if(!d)return '<section class="parks-evidence"><h3>Rouge park context unavailable</h3><p>The park records did not load. Reload to retry; no park screening result is available.</p></section>';
 return '<section class="parks-evidence"><span class="eyebrow">ROUGE NATIONAL URBAN PARK</span><h3>Park coverage needs review.</h3><p class="parks-notice">Two federal sources show different extents. We keep them separate; an overall park-impact result is unknown.</p><div class="parks-results">'+[['nrcan','NRCan legislative record','Retrieved September 2026'],['cpcad','CPCAD conservation record','December 2025 snapshot']].map(([key,label,date])=>'<article><span class="park-swatch '+key+'"></span><div><strong>'+label+'</strong><span>'+parkOverlap(d.records[key])+'</span><small>'+date+'</small></div></article>').join('')+'</div><p>No overlap in these records does not rule out an effect on park lands or habitats. Verify the current boundary and land status with Parks Canada.</p><button type="button" id="show-rouge" class="parks-map-button">Compare Rouge records on the map <span aria-hidden="true">↗</span></button><details><summary>What can transit learn from Rouge?</summary><p>The park’s 2019 management plan promotes transit and shuttle access while calling for infrastructure planning to consider wildlife movement, drainage, cumulative effects and cultural heritage. It describes wildlife culverts added or modified during Sewells Road resurfacing.</p><p>For a transit concept, compare better access to existing park entrances with a new crossing. Consider habitat connections, worksites and drainage alongside passenger convenience. These are questions to investigate, not a recommendation to build through the park.</p><p>The Rouge Act gives ecological integrity first priority in park management and includes authorization provisions for infrastructure. A mapped overlap alone cannot decide whether a specific project is permitted.</p><a href="'+PARK_SOURCES.plan+'" target="_blank" rel="noreferrer">Parks Canada’s management plan ↗</a><a href="'+PARK_SOURCES.law+'" target="_blank" rel="noreferrer">Rouge National Urban Park Act ↗</a></details><details><summary>Compare sources and methods</summary><p>The NRCan live service and December 2025 CPCAD record differ spatially. Their separate outlines are not combined into a new park boundary. The NRCan download also differed from its live service during our check.</p><p>Results use 2D intersections with each full source geometry, including edge contact. Display copies alone are simplified by 5 m. September 14, 2026 is the retrieval date, not a legal effective date. This screen covers Rouge only and leaves park-wide coverage unresolved. Rankings and costs are unchanged.</p><a href="'+PARK_SOURCES.nrcan+'" target="_blank" rel="noreferrer">NRCan boundary catalogue ↗</a><a href="'+PARK_SOURCES.cpcad+'" target="_blank" rel="noreferrer">CPCAD conservation database ↗</a><a href="data/rouge-park.json" target="_blank" rel="noreferrer">Source records, methods and licence ↗</a></details></section>';
}
export function addParkLayers(map,data,showPopup){
 map.addSource('rouge-parks',{type:'geojson',data});
 for(const [id,color] of [['nrcan','#32644d'],['cpcad','#925667']]){
  map.addLayer({id:'park-'+id+'-fill',type:'fill',source:'rouge-parks',filter:['==',['get','id'],id],layout:{visibility:'none'},paint:{'fill-color':color,'fill-opacity':.12}});
  map.addLayer({id:'park-'+id+'-border',type:'line',source:'rouge-parks',filter:['==',['get','id'],id],layout:{visibility:'none'},paint:{'line-color':color,'line-width':2,...(id==='cpcad'?{'line-dasharray':[3,2]}:{})}});
 }
 map.on('click',event=>{
  if(map.getLayoutProperty('park-nrcan-fill','visibility')==='none')return;
  if(map.queryRenderedFeatures(event.point,{layers:['proposal-line','concept-stops'].filter(id=>map.getLayer(id))}).length)return;
  const hits=map.queryRenderedFeatures(event.point,{layers:['park-nrcan-fill','park-cpcad-fill']});
  if(!hits.length)return;
  const labels=[...new Set(hits.map(f=>f.properties.label))];
  const content=document.createElement('div');content.className='stop-popup';const title=document.createElement('strong');title.textContent='Rouge · '+labels.join(' + ');const p=document.createElement('p');p.textContent='Federal records have different extents. Overall park coverage is unresolved. These outlines do not establish construction permission or the absence of impacts.';content.append(title,p);showPopup(event.lngLat,content);
 });
}
